const fs = require("fs");
const path = require("path");
const { withAppBuildGradle } = require("expo/config-plugins");

// android/ is regenerated by every `expo prebuild`, so the release key lives in
// keystores/ (gitignored; CI writes it from a secret) and this plugin copies it
// in and signs release builds with it. Passwords are read from environment
// variables at build time and never written into build.gradle.
const KEYSTORE = path.join("keystores", "greenmail-release.p12");

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    const root = config.modRequest.projectRoot;
    const source = path.join(root, KEYSTORE);
    // No key here (e.g. a developer's machine): release builds stay debug-signed.
    if (!fs.existsSync(source)) return config;

    const appDir = path.join(root, "android", "app");
    fs.mkdirSync(appDir, { recursive: true });
    fs.copyFileSync(source, path.join(appDir, "release.p12"));

    let contents = config.modResults.contents;
    if (contents.includes("storeFile file('release.p12')")) return config;

    const block = `        release {
            storeFile file('release.p12')
            storeType 'pkcs12'
            storePassword System.getenv("GREENMAIL_RELEASE_STORE_PASSWORD")
            keyAlias System.getenv("GREENMAIL_RELEASE_KEY_ALIAS")
            keyPassword System.getenv("GREENMAIL_RELEASE_KEY_PASSWORD")
        }`;
    contents = contents.replace(/(signingConfigs\s*\{[\s\S]*?debug\s*\{[\s\S]*?\}\n)(\s*\})/, `$1${block}\n$2`);
    // The release build type: anchor on the template's comment above it (not on "release {", now also a signing config).
    contents = contents.replace(
      /(\/\/ Caution! In production, you need to generate your own keystore file\.[\s\S]*?)signingConfig signingConfigs\.debug/,
      "$1signingConfig signingConfigs.release",
    );
    config.modResults.contents = contents;
    return config;
  });
};
